"""Pydantic schemas for description optimization iterations and round records."""

from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field

class CandidateDescriptions(BaseModel):
    """Structured dictionary of candidate descriptions generated by the optimizer."""
    descriptions: Dict[str, str] = Field(
        ...,
        description="Map of tool name to refined description. Must contain all 10 canonical tools.",
    )

class ValidationResult(BaseModel):
    """Result of candidate description validation checks."""
    is_valid: bool
    rejection_reason: Optional[str] = None

class DescriptionDiff(BaseModel):
    """Before and after description comparison for a tool."""
    tool_name: str
    before_description: str
    after_description: str
    changed: bool = True

class OptimizationRoundRecord(BaseModel):
    """Detailed record of an individual optimization round."""
    round_number: int
    best_accuracy_before: float
    candidate_accuracy: Optional[float] = None
    accuracy_delta: Optional[float] = None
    accepted: bool
    rejection_reason: Optional[str] = None
    current_descriptions: Dict[str, str]
    candidate_descriptions: Optional[Dict[str, str]] = None
    mistakes_input: List[Dict[str, Any]] = Field(default_factory=list)
    model: str
    candidate_tool_definition_hash: Optional[str] = None
    dataset_hash: str
    timestamp: str
    description_diffs: List[DescriptionDiff] = Field(default_factory=list)

class OptimizationSummary(BaseModel):
    """Overall summary of a complete optimization run."""
    run_id: str
    model: str
    initial_accuracy: float
    final_accuracy: float
    accuracy_improvement: float
    total_rounds: int
    accepted_rounds: int
    best_round: int
    consecutive_non_improvements: int
    stop_reason: str
    best_tool_definition_hash: str
    dataset_hash: str
    best_descriptions: Dict[str, str]
    rounds: List[OptimizationRoundRecord] = Field(default_factory=list)
